      "node": "Sigma3Node"
    },
    "out": "string"
  },
  "expr": {
    "args": [
      {
        "name": "node",
        "type": "Sigma3Node"
      }
    ],
    "ret": "string",
    "body": "sha256(JSON.stringify({essence, io, expr, parents}))"
  },
  "implementation": {
    "ts": "const { encodeHex } = await import(\"jsr:@std/encoding/hex\");\nconst payload = JSON.stringify({\n  essence: node.essence,\n  io: node.io,\n  expr: node.expr,\n  parents: node.identity.parents\n});\nconst msgUint8 = new TextEncoder().encode(payload);\nconst hashBuffer = await crypto.subtle.digest('SHA-256', msgUint8);\nreturn encodeHex(hashBuffer);"
  },
  "mutation_log": []
}

{
  "identity": {
    "structural_hash": "15d6bba9c12c53de3f1975258b967c76930ad6937f8f3fc0133fcd1e17047456",
    "context_hash": "core",
    "version": 1,
    "parents": []
  },
  "essence": {
    "type": "meta_fn",
    "level": 1,
    "substrate": "ts"
  },
  "physics": {
    "energy_cost": 10,
    "stability": 1
  },
  "io": {
    "in": {
      "state": "State",
      "targetAlias": "string",
      "path": "(string|number)[]",
      "newValue": "any",
      "executeNeuron": "Function"
    },
    "out": "TransformResult<State>"
  },
  "expr": {
    "args": [
      {
        "name": "state",
        "type": "State"
      },
      {
        "name": "targetAlias",
        "type": "string"
      },
      {
        "name": "path",
        "type": "(string|number)[]"
      },
      {
        "name": "newValue",
        "type": "any"
      },
      {
        "name": "executeNeuron",
        "type": "Function"
      }
    ],
    "ret": "TransformResult<State>",
    "body": "state' = apply_ir_mutation(...)"
  },
  "implementation": {
    "ts": "const next = structuredClone(state);\n        const diff = { added: [], updated: [], removed: [] };\n\n        const targetNode = next[targetAlias];\n        if (!targetNode) {\n          throw new Error(`Neuron ${targetAlias} not found in state.`);\n        }\n\n        const oldHash = targetNode.identity.structural_hash;\n        \n        // Mutate the IR tree by following the path\n        let current = targetNode.expr;\n        for (let i = 0; i < path.length - 1; i++) {\n            current = current[path[i]];\n        }\n        current[path[path.length - 1]] = newValue;\n        \n        // Execute the hash neuron to calculate the new hash\n        const newHash = await executeNeuron(next, \"calculate_structural_hash\", { node: targetNode });\n        \n        targetNode.identity = {\n          ...targetNode.identity,\n          structural_hash: newHash,\n          parents: [oldHash],\n          version: targetNode.identity.version + 1\n        };\n        \n        targetNode.mutation_log.push(`Mutated IR at [${path.join(\".\")}] to: ${JSON.stringify(newValue)} -> [${newHash}]`);\n        diff.updated.push(targetAlias);\n\n        return { next, diff };"
  },
  "mutation_log": []
}

