    "ts": "const targetNode = state[nodeAlias];\n        if (!targetNode) throw new Error(`Neuron ${nodeAlias} not found`);\n        const irJson = await Dispatcher.foldForRust(targetNode);\n        console.log(`[RUST BRIDGE] 📤 Sending IR for ${nodeAlias} to Rust Compiler...`);\n        console.log(`[RUST BRIDGE] IR Payload: ${irJson}`);\n        console.log(`[RUST BRIDGE] 📥 Awaiting implementation of WASM linker...`);\n        // Deno.run({ cmd: [\"cargo\", \"run\", \"--\", irJson] });"
